def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", {})
    outcome = result.get("outcome")
    credit_limit = result.get("credit_limit", 0)

    # Network referral rule: self_employed with requested_limit > 6000
    # must go to manual review instead of being issued. A decline stays a decline.
    is_self_employed = app.get("employment") == "self_employed"
    requested_limit = app.get("requested_limit", 0)
    needs_review = is_self_employed and requested_limit > 6000

    if outcome == "approved":
        if needs_review:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": credit_limit}
    elif outcome == "declined":
        return {"action": "decline", "limit": 0}
    elif outcome == "manual_review":
        return {"action": "queue_review", "limit": 0}
    else:
        # Unknown outcome - treat as manual review to be safe
        return {"action": "queue_review", "limit": 0}
